from datetime import datetime, timedelta, timezone

def display_at_offset(utc_time, offset_minutes):
    if utc_time.tzinfo is None or utc_time.utcoffset() != timedelta(0):
        raise ValueError('an aware UTC datetime is required')
    fixed_zone = timezone(timedelta(minutes=offset_minutes))
    return utc_time.astimezone(fixed_zone)
